sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
		var charRegex = /[^a-zA-Z0-9\s]/g;
        // Including the same on Chnage script when Bulk record already has amend trade while creation and loading
        var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
        eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
        eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
        eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
        eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
        eligbleCheck.getXMLAnswer(handleEligiblity);

        function handleEligiblity(check) {
            if (check.toString() == 'true') {
                var populateBulkFields = new GlideAjax('x_hsb11_hsbc_mss_o.MSSAmendUtilsCore');
                populateBulkFields.addParam('sysparm_name', 'getTradeFieldvaluesForBulk');
                populateBulkFields.addParam('sysparm_bulkID', g_form.getUniqueValue());
                populateBulkFields.getXMLAnswer(populateField);

            }

            function populateField(response) {
                if (response.toString() != 'false') { // populating only for active bulk if there is a active maker task
                    var answer = JSON.parse(response);
                    //handling special Characters
                    var cusRef = answer.cusRef;
                    if ((cusRef != null) && (cusRef != '') && (cusRef != undefined)) {
                        cusRef = cusRef.replace(charRegex, "");
                        cusRef = cusRef.replace(/\s/g, ''); //space removal
                    }
                    var susAccNum = answer.susAccNum;
                    if ((susAccNum != null) && (susAccNum != '') && (susAccNum != undefined)) {
                        susAccNum = susAccNum.replace(charRegex, "");
                        susAccNum = susAccNum.replace(/\s/g, ''); //space removal
                    }
                    var accOfClient = answer.accOfClient;
                    if ((accOfClient != null) && (accOfClient != '') && (accOfClient != undefined)) {
                        accOfClient = accOfClient.replace(charRegex, "");
                        accOfClient = accOfClient.replace(/\s/g, ''); //space removal
                    }
                    var delivererCusBic = answer.delivererCusBic;
                    if ((delivererCusBic != null) && (delivererCusBic != '') && (delivererCusBic != undefined)) {
                        delivererCusBic = delivererCusBic.replace(charRegex, "");
                        delivererCusBic = delivererCusBic.replace(/\s/g, ''); //space removal
                    }
                    var placeofSett = answer.placeofSett;
                    if ((placeofSett != null) && (placeofSett != '') && (placeofSett != undefined)) {
                        placeofSett = placeofSett.replace(charRegex, "");
                        placeofSett = placeofSett.replace(/\s/g, ''); //space removal
                    }
                    var sellBuyBic = answer.sellBuyBic;
                    if ((sellBuyBic != null) && (sellBuyBic != '') && (sellBuyBic != undefined)) {
                        sellBuyBic = sellBuyBic.replace(charRegex, "");
                        sellBuyBic = sellBuyBic.replace(/\s/g, ''); //space removal
                    }
                    //handling special Characters
                    var requestHeaders = [answer.securityID, answer.tradeDate, answer.settlementDate, answer.dealPrice, answer.dealCurrency, answer.settlementCurrency, answer.settlementAmount, answer.counterPartyRef, cusRef, answer.locCode, answer.hmiIndicator, answer.scripholIndicator, answer.cashHoldIndicator, answer.gdiIncidcator, answer.payMethod, answer.switchIndicator, answer.switchAcc, answer.counterParCode, delivererCusBic, sellBuyBic, placeofSett, accOfClient, answer.converAccSwitch, answer.counterSettAccNum, susAccNum, answer.amendChargesType, answer.amendChargesCCY, answer.amendChargesAmt, answer.amendNSSC]; // request body header
                    var bulkFields = ['security_id_sec_id', 'amend_trade_date', 'settlement_date', 'amend_deal_price', 'amend_deal_currency', 'amend_settlement_currency', 'amend_settlement_amount', 'counterparty_reference', 'customer_reference', 'amend_location_code', 'amend_hmi_indicator', 'amend_script_hold_indicator', 'amend_cash_hold_indicator', 'amend_gdi_indicator', 'amend_payment_method', 'amend_switch_indicator', 'amend_switch_account', 'amend_counterparty_code', 'amend_deliverer_custodian_bic_receiver_custodian_bic', 'amend_seller_bic_buyer_bic', 'amend_place_of_settlement_bic', 'amend_a_c_of_client', 'amend_convert_to_account_switching', 'amend_counterparty_settlement_account_number', 'amend_suspense_account_number', 'amend_charges_type', 'amend_charges_ccy', 'amend_charges_amt', 'amend_nssc']; //populate amend values
                    for (var i = 0; i < requestHeaders.length; i++) {
                        if ((requestHeaders[i] != '') && (requestHeaders[i] != null) && (requestHeaders[i] != undefined)) {
                            g_form.setValue(bulkFields[i], requestHeaders[i]);
                        }
                    }
                }
            }

        }
        //Including the same on Chnage script when Bulk record already has amend trade while creation and loading

        return;
    }

    /*Artifacts Included:
    1) Client Script: MSS Bulk Prepopulate Amend from Trade
    2) Script Include: x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
    3) Script Include: x_hsb11_hsbc_mss_o.MSSAmendUtilsCore - getTradeFieldvaluesForBulk
    4) System Property: x_hsb11_mss_c_proc.enableautomatedamend.market
    5) System Property: x_hsb11_mss_c_proc.enableautomatedamend.outcomes

    */



    var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
    eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
    eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
    eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
    eligbleCheck.getXMLAnswer(handleEligiblity);

	var charRegex = /[^a-zA-Z0-9\s]/g;

    function handleEligiblity(check) {
        if (check.toString() == 'true') {
            var populateBulkFields = new GlideAjax('x_hsb11_hsbc_mss_o.MSSAmendUtilsCore');
            populateBulkFields.addParam('sysparm_name', 'getTradeFieldvaluesForBulk');
            populateBulkFields.addParam('sysparm_bulkID', g_form.getUniqueValue());
            populateBulkFields.getXMLAnswer(populateField);

        }

        function populateField(response) {
            if (response.toString() != 'false') { // populating only for active bulk if there is a active maker task
                var answer = JSON.parse(response);


                //handling special Characters
                var cusRef = answer.cusRef;
                if ((cusRef != null) && (cusRef != '') && (cusRef != undefined)) {
                    cusRef = cusRef.replace(charRegex, "");
                    cusRef = cusRef.replace(/\s/g, ''); //space removal
                }
                var susAccNum = answer.susAccNum;
                if ((susAccNum != null) && (susAccNum != '') && (susAccNum != undefined)) {
                    susAccNum = susAccNum.replace(charRegex, "");
                    susAccNum = susAccNum.replace(/\s/g, ''); //space removal
                }
                var accOfClient = answer.accOfClient;
                if ((accOfClient != null) && (accOfClient != '') && (accOfClient != undefined)) {
                    accOfClient = accOfClient.replace(charRegex, "");
                    accOfClient = accOfClient.replace(/\s/g, ''); //space removal
                }
                var delivererCusBic = answer.delivererCusBic;
                if ((delivererCusBic != null) && (delivererCusBic != '') && (delivererCusBic != undefined)) {
                    delivererCusBic = delivererCusBic.replace(charRegex, "");
                    delivererCusBic = delivererCusBic.replace(/\s/g, ''); //space removal
                }
                var placeofSett = answer.placeofSett;
                if ((placeofSett != null) && (placeofSett != '') && (placeofSett != undefined)) {
                    placeofSett = placeofSett.replace(charRegex, "");
                    placeofSett = placeofSett.replace(/\s/g, ''); //space removal
                }
                var sellBuyBic = answer.sellBuyBic;
                if ((sellBuyBic != null) && (sellBuyBic != '') && (sellBuyBic != undefined)) {
                    sellBuyBic = sellBuyBic.replace(charRegex, "");
                    sellBuyBic = sellBuyBic.replace(/\s/g, ''); //space removal
                }
                //handling special Characters
                var requestHeaders = [answer.securityID, answer.tradeDate, answer.settlementDate, answer.dealPrice, answer.dealCurrency, answer.settlementCurrency, answer.settlementAmount, answer.counterPartyRef, cusRef, answer.locCode, answer.hmiIndicator, answer.scripholIndicator, answer.cashHoldIndicator, answer.gdiIncidcator, answer.payMethod, answer.switchIndicator, answer.switchAcc, answer.counterParCode, delivererCusBic, sellBuyBic, placeofSett, accOfClient, answer.converAccSwitch, answer.counterSettAccNum, susAccNum, answer.amendChargesType, answer.amendChargesCCY, answer.amendChargesAmt, answer.amendNSSC]; // request body header
                var bulkFields = ['security_id_sec_id', 'amend_trade_date', 'settlement_date', 'amend_deal_price', 'amend_deal_currency', 'amend_settlement_currency', 'amend_settlement_amount', 'counterparty_reference', 'customer_reference', 'amend_location_code', 'amend_hmi_indicator', 'amend_script_hold_indicator', 'amend_cash_hold_indicator', 'amend_gdi_indicator', 'amend_payment_method', 'amend_switch_indicator', 'amend_switch_account', 'amend_counterparty_code', 'amend_deliverer_custodian_bic_receiver_custodian_bic', 'amend_seller_bic_buyer_bic', 'amend_place_of_settlement_bic', 'amend_a_c_of_client', 'amend_convert_to_account_switching', 'amend_counterparty_settlement_account_number', 'amend_suspense_account_number', 'amend_charges_type', 'amend_charges_ccy', 'amend_charges_amt', 'amend_nssc']; //populate amend values
                for (var i = 0; i < requestHeaders.length; i++) {
                    if ((requestHeaders[i] != '') && (requestHeaders[i] != null) && (requestHeaders[i] != undefined)) {
                        g_form.setValue(bulkFields[i], requestHeaders[i]);
                    }
                }
            }
        }

    }
}
